// Helper function to get words by difficulty
export function getWordsByDifficulty(difficulty: 'easy' | 'medium' | 'hard' | 'expert'): WordEntry[] {
  return WORD_DATABASE.filter(w => w.difficulty === difficulty);
}

// Helper function to get words by category
export function getWordsByCategory(category: string): WordEntry[] {
  return WORD_DATABASE.filter(w => w.category === category);
}

// Helper function to get random word
export function getRandomWord(difficulty?: 'easy' | 'medium' | 'hard' | 'expert'): WordEntry {
  const words = difficulty ? getWordsByDifficulty(difficulty) : WORD_DATABASE;
  return words[Math.floor(Math.random() * words.length)];
}
